import {createAtmosphereHost} from './atmosphere-host.js';
import * as T from 'three';
import {GLTFLoader} from '/vendor/loaders/GLTFLoader.js';
import {OrbitControls} from '/vendor/OrbitControls.js';
import {RanchRenderer} from './ranch-renderer.js';
const presets={home:'simulation-assets/buildings/family-home-complete.glb',castle:'castle-assets/EH-001.sunward-castle.glb',work:'domestic-assets/GF-191.glb',coast:'coastal-assets/CE-006.glb'};
const views=[],loader=new GLTFLoader(),comparison=document.querySelector('#comparison'),status=document.querySelector('#status');
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');
let sky={enabled:false,environment:'earth',time:'day',weather:'clear',intensity:.5,reducedMotion:motionPreference.matches},atmosphereHost=null,skySeconds=0;
let asset='',mode='split',revision=0,busy=false,records=[],syncing=false,serial=0;
for(const id of ['before','after']){
 const host=document.getElementById(id),renderer=id==='after'?new RanchRenderer({antialias:true}):new T.WebGLRenderer({antialias:true,preserveDrawingBuffer:true});
 renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.outputColorSpace=T.SRGBColorSpace;host.append(renderer.domElement);
 const scene=new T.Scene();scene.background=new T.Color('#e3e7d6');scene.add(new T.HemisphereLight('#ffffff','#8b927e',1.3));const sun=new T.DirectionalLight('#ffffff',2);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.normalBias=.025;scene.add(sun,sun.target);
 const camera=new T.PerspectiveCamera(35,1,.01,1000),controls=new OrbitControls(camera,renderer.domElement);controls.enableDamping=false;controls.mouseButtons={LEFT:null,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};
 const view={id,host,renderer,scene,sun,camera,controls,model:null,floor:null};views.push(view);
 controls.addEventListener('change',()=>{if(syncing)return;syncing=true;for(const other of views){if(other===view)continue;other.camera.position.copy(camera.position);other.camera.quaternion.copy(camera.quaternion);other.controls.target.copy(controls.target);other.controls.update();}syncing=false;draw();window.RanchView?.changed();});
 new ResizeObserver(resize).observe(host);
}
function draw(){for(const v of views)if(v.host.clientWidth&&v.host.clientHeight)v.renderer.render(v.scene,v.camera);}
function resize(){for(const v of views){const w=v.host.clientWidth,h=v.host.clientHeight;if(!w||!h)continue;v.renderer.setSize(w,h,false);v.camera.aspect=w/h;v.camera.updateProjectionMatrix();}if(views[0]?.model)fit();else draw();}
function fit(){if(!views[0].model)return;const box=new T.Box3().setFromObject(views[0].model),size=box.getSize(new T.Vector3()),center=box.getCenter(new T.Vector3()),radius=Math.max(size.length()/2,.1);syncing=true;const aspect=Math.min(...views.filter(v=>v.host.clientWidth).map(v=>v.host.clientWidth/v.host.clientHeight));const distance=radius/Math.sin(Math.atan(Math.tan(T.MathUtils.degToRad(17.5))*Math.min(1,aspect)))*1.15;for(const v of views){v.camera.position.copy(center).add(new T.Vector3(1,.65,1.2).normalize().multiplyScalar(distance));v.camera.near=radius/100;v.camera.far=distance+radius*40;v.camera.updateProjectionMatrix();v.controls.target.copy(center);v.controls.minDistance=radius*.6;v.controls.maxDistance=radius*30;v.controls.update();}syncing=false;draw();window.RanchView?.changed();}
function dispose(root){root?.traverse(o=>{o.geometry?.dispose();for(const m of [].concat(o.material||[]))m.dispose();});}
async function choose(path){if(!records.some(r=>r.path===path))throw Error('Unknown asset');const token=++serial;busy=true;status.textContent='Loadingâ€¦';window.RanchView?.changed();try{const loaded=await Promise.all([loader.loadAsync('/'+path),loader.loadAsync('/'+path)]);if(token!==serial){loaded.forEach(g=>dispose(g.scene));return;}atmosphereHost?.dispose();atmosphereHost=null;for(const [i,v]of views.entries()){for(const old of [v.model,v.floor])if(old){v.scene.remove(old);dispose(old);}v.model=loaded[i].scene;v.model.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});v.scene.add(v.model);const b=new T.Box3().setFromObject(v.model),s=b.getSize(new T.Vector3()),c=b.getCenter(new T.Vector3()),r=Math.max(s.length(),1);v.floor=new T.Mesh(new T.CircleGeometry(r*.85,64),new T.MeshStandardMaterial({color:'#d5dbc3',roughness:1}));v.floor.material.userData.materialRole='ground';v.floor.rotation.x=-Math.PI/2;v.floor.position.set(c.x,b.min.y-.005,c.z);v.floor.receiveShadow=true;v.scene.add(v.floor);v.sun.position.copy(c).add(new T.Vector3(-r,r*1.5,r));v.sun.target.position.copy(c);Object.assign(v.sun.shadow.camera,{left:-r,right:r,top:r,bottom:-r,near:.01,far:r*7});v.sun.shadow.camera.updateProjectionMatrix();}asset=path;revision++;document.querySelector('#asset').value=path;for(const b of document.querySelectorAll('[data-preset]'))b.setAttribute('aria-pressed',String(presets[b.dataset.preset]===path));status.textContent='Ready · same geometry on both sides';resize();fit();attachSky();}catch(e){status.textContent='Could not load asset. Choose another model.';throw e;}finally{if(token===serial){busy=false;window.RanchView?.changed();}}}
function setMode(value){if(!['split','before','after'].includes(value))throw Error('Unknown mode');mode=value;comparison.dataset.mode=value;for(const b of document.querySelectorAll('#modes button'))b.setAttribute('aria-pressed',String(b.dataset.mode===mode));revision++;resize();fit();window.RanchView?.changed();}
document.querySelector('#asset').onchange=e=>choose(e.target.value).catch(console.error);document.querySelector('#fit').onclick=fit;document.querySelector('#presets').onclick=e=>{if(e.target.dataset.preset)choose(presets[e.target.dataset.preset]).catch(console.error);};document.querySelector('#modes').onclick=e=>{if(e.target.dataset.mode)setMode(e.target.dataset.mode);};window.addEventListener('resize',resize);
const read=()=>({atmosphere:atmosphereHost?.read()||{enabled:false},asset,mode,revision,busy,availableModels:records.length,baseline:'original GLB materials + neutral lighting; not historical renderer',after:'quiet-materials-v1',sameGeometry:true,texturesAdded:false,camera:views[0].camera.position.toArray()});
window.RanchView?.register('effectBrowser',read,draw);
window.RanchActions?.register('effectBrowser',{revision:()=>revision,read,unavailable:()=>busy?'Loading asset':null,actions:{atmosphere:{description:'Set presentation atmosphere; no gameplay changes',schema:{type:'object',properties:{enabled:{type:'boolean'},environment:{type:'string',enum:['earth','interior','vacuum']},time:{type:'string',enum:['day','dusk','night']},weather:{type:'string',enum:['clear','clouds','rain','snow','mist']},intensity:{type:'number',minimum:0,maximum:1},reducedMotion:{type:'boolean'}}},run:settings=>setSky(settings)},select:{description:'Compare a library model',schema:{type:'object',properties:{path:{type:'string'}},required:['path']},run:({path})=>choose(path)},mode:{description:'Show both, before or after',schema:{type:'object',properties:{value:{type:'string',enum:['split','before','after']}},required:['value']},run:({value})=>setMode(value)},fit:{description:'Reset synchronized cameras',schema:{type:'object',properties:{}},run:()=>{fit();revision++;}}}});
fetch('/model-visual-index.json').then(r=>{if(!r.ok)throw Error('Library unavailable');return r.json();}).then(async index=>{records=index.models;const select=document.querySelector('#asset');for(const r of records){const o=document.createElement('option');o.value=r.path;o.textContent=r.path.replace(/\.glb$/,'');select.append(o);}await choose(presets.home);if(matchMedia('(max-width:799px)').matches)setTimeout(()=>window.RanchDrawers?.close(),200);}).catch(e=>{status.textContent='Unable to load library. Reload to retry.';console.error(e);});

function attachSky(){const v=views[1];if(!v.model)return;const box=new T.Box3().setFromObject(v.model);atmosphereHost=createAtmosphereHost(T,v.scene,{center:box.getCenter(new T.Vector3()),span:Math.max(box.getSize(new T.Vector3()).length(),1),camera:v.camera,lights:v.scene.children.filter(o=>o.isLight)});atmosphereHost.set(sky);draw();}
function setSky(settings){const next={...sky,...settings};if(motionPreference.matches)next.reducedMotion=true;atmosphereHost?.set(next);sky=next;skySeconds=0;revision++;for(const b of document.querySelectorAll('[data-time]'))b.setAttribute('aria-pressed',String(b.dataset.time===(sky.enabled?sky.time:'off')));for(const b of document.querySelectorAll('[data-weather]'))b.setAttribute('aria-pressed',String(b.dataset.weather===sky.weather));document.querySelector('#sky-environment').value=sky.environment;document.querySelector('#sky-intensity').value=sky.intensity*100;document.querySelector('#sky-value').value=Math.round(sky.intensity*100)+'%';document.querySelector('#sky-motion').checked=sky.reducedMotion;document.querySelector('#caption').textContent=sky.enabled?'Original asset materials → quiet materials + '+sky.time+' atmosphere':'Original asset materials → quiet materials, lighting and contours';draw();window.RanchView?.changed();return atmosphereHost?.read();}
document.querySelector('#sky-times').onclick=e=>{if(e.target.dataset.time)setSky(e.target.dataset.time==='off'?{enabled:false}:{enabled:true,time:e.target.dataset.time});};
document.querySelector('#sky-weather').onclick=e=>{if(e.target.dataset.weather)setSky({enabled:true,weather:e.target.dataset.weather});};
document.querySelector('#sky-environment').onchange=e=>setSky({environment:e.target.value});
document.querySelector('#sky-intensity').oninput=e=>setSky({intensity:Number(e.target.value)/100});
document.querySelector('#sky-motion').checked=sky.reducedMotion;
document.querySelector('#sky-motion').onchange=e=>setSky({reducedMotion:e.target.checked});
motionPreference.addEventListener('change',e=>setSky({reducedMotion:e.matches}));
let lastFrame=0;function animate(now){const delta=Math.min((now-lastFrame)/1000,.05);lastFrame=now;if(!document.hidden&&sky.enabled&&!sky.reducedMotion){skySeconds+=delta;atmosphereHost?.update(skySeconds);draw();}requestAnimationFrame(animate);}requestAnimationFrame(animate);
window.addEventListener('pagehide',()=>atmosphereHost?.dispose());
